 body.innerHTML=designerParts.length?designerParts.map((p,i)=>'<tr>'+dclFields.map(f=>{const numeric=['l','w','t','qty','edgeBandThickness'].includes(f);const options=f==='grain'?['Verify','Lengthwise','Crosswise','No grain']:['edgeL1','edgeL2','edgeW1','edgeW2'].includes(f)?['Verify','Banded','No band']:f==='edgeBand'?['Verify','None','Front only','Front + 2 sides','All four edges','Custom']:f==='liner'?['Not set','None','Liner','Backer','Both','Verify']:f==='qa'?['Needs review','Checked']:null;let control;if(options)control='<select data-dcl-index="'+i+'" data-dcl-field="'+f+'">'+options.map(o=>'<option'+(String(p[f]??'')===o?' selected':'')+'>'+safe(o)+'</option>').join('')+'</select>';else control='<input data-dcl-index="'+i+'" data-dcl-field="'+f+'" '+(numeric?'type="number" min="0" step="'+(f==='edgeBandThickness'?'0.1':'1')+'"':'type="text"')+' value="'+safe(p[f]??'')+'" '+(f==='name'?'aria-label="Part name"':'')+'>';return '<td>'+control+'</td>';}).join('')+'<td><button type="button" class="light-btn" data-dcl-remove="'+i+'" aria-label="Remove part row">Remove</button></td></tr>').join(''):'<tr><td colspan="'+(dclFields.length+1)+'">No designer parts yet. Configure the cabinet, then choose “Regenerate from design”.</td></tr>';
 const qty=designerParts.reduce((n,p)=>n+Math.max(0,Number(p.qty)||0),0),area=designerParts.reduce((n,p)=>n+Math.max(0,Number(p.l)||0)*Math.max(0,Number(p.w)||0)*Math.max(0,Number(p.qty)||0),0)/92903.04;
 $d('#dcMetricRows').textContent=designerParts.length;$d('#dcMetricQty').textContent=qty;$d('#dcMetricArea').textContent=area.toFixed(2)+' ft²';
 const allChecked=designerParts.length>0&&designerParts.every(p=>p.qa==='Checked');$d('#dcMetricReview').textContent=allChecked?'Checked':'Unverified';
